import math

def catalan(k):
    """Computes the k-th Catalan number C_k."""
    if k < 0:
        return 0
    if k == 0:
        return 1
    # C_k = 1/(k+1) * C(2k, k)
    try:
        return math.comb(2 * k, k) // (k + 1)
    except AttributeError:
        # Handle older Python versions without math.comb
        def combinations(n, k):
            if k < 0 or k > n:
                return 0
            if k == 0 or k == n:
                return 1
            if k > n // 2:
                k = n - k
            res = 1
            for i in range(k):
                res = res * (n - i) // (i + 1)
            return res
        return combinations(2 * k, k) // (k + 1)

def check_identity(N):
    # LHS: Sum_{k=0}^{N} C_k / (k+1)
    lhs = 0
    for k in range(N + 1):
        C_k = catalan(k)
        lhs += C_k / (k + 1)

    # RHS: (-1)^{N-1} * N / (N+1)
    if N == 0:
        rhs = 0.0 # Handling the undefined exponent N-1 for N=0, but following the formula structure
    else:
        rhs = ((-1)**(N - 1)) * N / (N + 1)

    return lhs, rhs

# Test small values of N
N_values = [0, 1, 2, 3]
results = {}
for N in N_values:
    lhs, rhs = check_identity(N)
    results[N] = (lhs, rhs)

print(results)
